		latestVersion,
		nextVersions,
		hasVersionUpdates,
		hasSignificantUpdates,
		areNotificationsEnabled,
		infoUrl,
		fetchVersions,
		setVersions,
		initialize,
		registerModalOpeners,
		checkForNewVersions,
		fetchWhatsNew,
		whatsNew,
		whatsNewArticles,
